From c164d99b0c53b391f36fcddc02a68f375aca2c70 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 14:17:41 +0100
Subject: [PATCH] components/calendar: Don't add events the model already has

Event plugins are shared by every calendar, so opening a second clock
while another one stays open made it receive the same events again and
list them twice. Events that are already present are now skipped.

BUG: 445979
---
 components/calendar/daysmodel.cpp | 24 +++++++++++++++++++-----
 1 file changed, 19 insertions(+), 5 deletions(-)

diff --git a/components/calendar/daysmodel.cpp b/components/calendar/daysmodel.cpp
index 60de15b2ff..823ef5bfbf 100644
--- a/components/calendar/daysmodel.cpp
+++ b/components/calendar/daysmodel.cpp
@@ -35,6 +35,11 @@ public:

 DaysModelPrivate::DaysModelPrivate() = default;

+static bool isSameEvent(const CalendarEvents::EventData &a, const CalendarEvents::EventData &b)
+{
+    return a.uid() == b.uid() && a.title() == b.title() && a.type() == b.type() && a.startDateTime() == b.startDateTime() && a.endDateTime() == b.endDateTime();
+}
+
 DaysModel::DaysModel(QObject *parent)
     : QAbstractItemModel(parent)
     , d(new DaysModelPrivate)
@@ -198,12 +203,21 @@ void DaysModel::onDataReady(const QMultiHash<QDate, CalendarEvents::EventData> &
     for (int i = 0; i < d->data->count(); i++) {
         const DayData &currentData = d->data->at(i);
         const QDate currentDate(currentData.yearNumber, currentData.monthNumber, currentData.dayNumber);
-        if (!data.values(currentDate).isEmpty()) {
-            const int addedEventCount = data.values(currentDate).count();
-
+        // Plugins are shared between all calendars, so this can be data we already have
+        QList<CalendarEvents::EventData> addedEvents;
+        for (const auto &dataDay : data.values(currentDate)) {
+            const auto existingEvents = d->eventsData.equal_range(currentDate);
+            const bool known = std::any_of(existingEvents.first, existingEvents.second, [&dataDay](const CalendarEvents::EventData &event) {
+                return isSameEvent(event, dataDay);
+            });
+            if (!known) {
+                addedEvents.append(dataDay);
+            }
+        }
+        if (!addedEvents.isEmpty()) {
             // Add event
-            beginInsertRows(index(i, 0), 0, addedEventCount - 1);
-            for (const auto &dataDay : data.values(currentDate)) {
+            beginInsertRows(index(i, 0), 0, addedEvents.count() - 1);
+            for (const auto &dataDay : std::as_const(addedEvents)) {
                 d->eventsData.insert(currentDate, dataDay);
             }
             endInsertRows();
-- 
